Description:
Received the tool but didn't work at first. Had to run script that added in_house tables. Script below.


CREATE TABLE `INHOUSE_REJECTREASONS` 
(
`id` INTEGER (11) NOT NULL AUTO_INCREMENT, 
`Reason` varchar (50), 
PRIMARY KEY (`id`)
) ENGINE=MyISAM;

ALTER TABLE `INHOUSE_REJECTREASONS` ADD Checked integer(10);
ALTER TABLE `INHOUSE_REJECTREASONS` ADD Total integer(10);

CREATE TABLE `INHOUSE_REJECTREPORT` 
(
`id` INTEGER (11) NOT NULL AUTO_INCREMENT, 
`ClientNumber` varchar (10),
`ClientName` varchar (50),  
`RejectReason` varchar (50), 
`PhoneNumber` varchar (10),
`RejectAmount` DOUBLE (10,2),  
`Balance` DOUBLE (10,2),  
PRIMARY KEY (`id`)
) ENGINE=MyISAM;

ALTER TABLE `INHOUSE_REJECTREPORT` ADD Email varchar(50);

ALTER TABLE INHOUSE_REJECTREPORT Add LastFour varchar(4);

CREATE TABLE `INHOUSE_EFTINFOPREVIEW` 
(
`id` integer (11) NOT NULL AUTO_INCREMENT , 
`ClientNumber` varchar (10), 
`Balance` double (10,2),
PRIMARY KEY (`id`)
) engine=MyISAM;

